private void addToAnythingButsMap(Map<NameState, List<Patterns>> map, NameState nameState, Patterns pattern) {
    if (!map.containsKey(nameState)) {
        map.put(nameState, new ArrayList<>());
    }
    map.get(nameState).add(pattern);
}
